  "implementation": "def solve(case):
    # Validate case structure
    if not isinstance(case, dict):
        raise ValueError("case must be a dict")
    if 'capacity' not in case or 'trials' not in case:
        raise ValueError("case missing required fields: capacity and trials")
    cap = case['capacity']
    if not isinstance(cap, int) or cap <= 0:
        raise ValueError("capacity must be a positive integer")
    trials = case['trials']
    if not isinstance(trials, list):
        raise ValueError("trials must be a list")
    for idx, t in enumerate(trials):
        if not isinstance(t, dict):
            raise ValueError(f"trial {idx} is not a dict")
        for key in ('signature', 'reflection', 'success'):
            if key not in t:
                raise ValueError(f"trial {idx} missing field '{key}'")
        if not isinstance(t['signature'], str):
            raise ValueError(f"trial {idx} signature must be string")
        if not isinstance(t['reflection'], str):
            raise ValueError(f"trial {idx} reflection must be string")
        if not isinstance(t['success'], bool):
            raise ValueError(f"trial {idx} success must be bool")

    # Process trials in order, deduplicate failures by signature (keep newest)
    # We'll store entries with their original index
    entries = []  # list of (signature, reflection, success, index)
    failure_latest = {}  # signature -> index of latest occurring failure
    for idx, t in enumerate(trials):
        sig = t['signature']
        ref = t['reflection']
        suc = t['success']
        entries.append((sig, ref, suc, idx))
        if not suc:
            # It's a failure; record latest index for this signature
            failure_latest[sig] = idx

    # Build deduplicated list: keep all successes, and for each failure signature keep only the latest
    kept_indices = set()
    for idx, (sig, ref, suc, _) in enumerate(entries):
        if suc:
            kept_indices.add(idx)
        else:
            # Failure: keep only if it is the latest occurrence of its signature
            if failure_latest.get(sig) == idx:
                kept_indices.add(idx)

    # Extract kept entries in chronological order
    kept = [entries[i] for i in range(len(entries)) if i in kept_indices]

    # Now truncate to capacity
    if len(kept) <= cap:
        final = kept
    else:
        # Separate failures and successes
        failures = []
        successes = []
        for sig, ref, suc, idx in kept:
            if not suc:
                failures.append((sig, ref, suc, idx))
            else:
                successes.append((sig, ref, suc, idx))

        # Sort failures by recency (descending index) then signature (ascending)
        failures.sort(key=lambda x: (-x[3], x[0]))
        # Sort successes similarly
        successes.sort(key=lambda x: (-x[3], x[0]))

        # Concatenate failures then successes, take first cap
        combined = failures + successes
        selected = combined[:cap]
        # Restore chronological order by original index
        selected.sort(key=lambda x: x[3])
        final = selected

    # Return list of dicts with only the required fields
    result = []
    for sig, ref, suc, idx in final:
        result.append({
            "signature": sig,
            "reflection": ref,
            "success": suc
        })
    return result
